import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const DEFAULT_DATA_FILE = 'data/library.json';

let dataFile = DEFAULT_DATA_FILE;

export function setDataFile(path) {
  dataFile = path ?? DEFAULT_DATA_FILE;
}

export function getDataFile() {
  return resolve(dataFile);
}

const EMPTY = { books: [], members: [], loans: [], sequences: { books: 0, members: 0, loans: 0 } };

export function load() {
  const file = getDataFile();
  if (!existsSync(file)) {
    return structuredClone(EMPTY);
  }
  let raw;
  try {
    raw = readFileSync(file, 'utf8');
  } catch (err) { ... }
  if (raw.trim() === '') return structuredClone(EMPTY);
  const parsed = JSON.parse(raw);
  return normalize(parsed);
}

export function save(state) {
  const file = getDataFile();
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, JSON.stringify(state, null, 2) + '\n');
}

export function read(fn) { const state = load(); const result = fn(state); save(state); return result; }
export function query(fn) { const state = load(); return fn(state); }
```

